// n8n Code node (JavaScript)
// Goal: always output { image_prompt: [<string>] }.
// Handles cases where input.output is either an object {image_prompt: "..."} or a plain string.
// Also strips markdown and optionally extracts a direct URL if present.

const item = $input.first().json;
const out = item.output;

// 1) Normalize to a string prompt
let promptText = "";

if (out && typeof out === "object") {
  // Old schema: { image_prompt: "..." }
  promptText = out.image_prompt ?? "";
} else if (typeof out === "string") {
  // New schema: plain text
  promptText = out;
} else {
  promptText = "";
}

// 2) If the model returned markdown with an image + URL, extract the best URL
// Prefer the last http(s) URL in the text (often the direct link).
const urlMatches = promptText.match(/https?:\/\/\S+/g) || [];
const bestUrl = urlMatches.length ? urlMatches[urlMatches.length - 1].replace(/[\)\]\s]+$/g, "") : "";

// 3) Remove markdown image syntax to avoid feeding junk downstream (optional but recommended)
promptText = promptText
  .replace(/!\[[^\]]*\]\([^)]+\)/g, "")   // remove markdown images
  .replace(/\n{3,}/g, "\n\n")            // collapse excessive newlines
  .trim();

// 4) Decide what downstream should receive:
// - If your next node expects a prompt to generate an image, you want a CLEAN PROMPT (not a URL).
// - If your next node expects an IMAGE URL, pass bestUrl instead.
// Choose ONE of these outputs:

// A) Use clean prompt text (recommended if next step is image generation):
const finalValue = promptText;

// B) Use extracted URL (use this if next step downloads the image):
// const finalValue = bestUrl;

const prompts = finalValue ? [finalValue] : [];

return [
  {
    json: {
      image_prompt: prompts,
      extracted_image_url: bestUrl, // helpful debug/optional downstream use
    },
  },
];

// Works whether the item looks like { output: {...} } or already flattened
const out = $json.output ?? $json;

const postContent =
  $('Content creator').first().json.output.topic + `\n\n` +
  $('Content creator').first().json.output.what_happened + `\n\n` +
  $('Content creator').first().json.output.why_it_happened + `\n\n` +
  $('Content creator').first().json.output.solution_and_takeaway;

return [{
  json: {
    ...$json,
    "post content": postContent,
    "post title": $('Content creator').first().json.output.topic,
    "image description": $('Content creator').first().json.output.image_description,
  }
}];

const text = $input.first().json['post content'] ?? '';

// Escape LinkedIn "little text format" reserved characters
// Includes: \ | { } @ [ ] ( ) < > # * _ ~
const escaped = text.replace(/[\\|{}@\[\]()<>\#*_~]/g, (m) => `\\${m}`);

return [{
  json: {
    ...$json,
    commentary_escaped: escaped,
  }
}];
